# Format: (file, symbol, start, end, role, method, excerpt_header)

def make_item(orig_item, locations, status, method, excerpt_lines):
    ci = orig_item['checklist_item']
    result = dict(orig_item)
    result['checklist_item'] = dict(ci)
    result['code_scope'] = {
        'locations': locations,
        'resolution_status': status,
        'resolution_error': '',
    }
    if method:
        result['code_scope']['resolution_method'] = method
    if excerpt_lines:
        result['code_excerpt'] = excerpt_lines
    else:
        result['code_excerpt'] = ''
    return result

